CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    email TEXT UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Define the migrations directory path
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads all SQL files from the migrations directory and logs them in order
 */
async function runMigrations() {
    try {
        console.log('Starting migration process...');
        console.log(`Reading migrations from: ${migrationsDir}`);

        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Migrations directory not found at ${migrationsDir}`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(migrationsDir, { recursive: true });
            console.log('Migrations directory created. Please add SQL migration files.');
            process.exit(0);
        }

        // Read all files from the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files (files ending with .sql)
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in the migrations directory.');
            console.log('Migration files should have a .sql extension.');
            process.exit(0);
        }

        console.log(`Found ${sqlFiles.length} migration file(s):`);

        // Sort files alphabetically/numerically to ensure they're applied in order
        // This assumes filenames start with numbers like 001_, 002_, etc.
        const sortedFiles = sqlFiles.sort((a, b) => {
            // Extract numbers from the beginning of filenames for sorting
            const numA = parseInt(a.match(/^(\d+)/)?.[1] || '0');
            const numB = parseInt(b.match(/^(\d+)/)?.[1] || '0');
            return numA - numB;
        });

        // Log each filename that would be applied
        let count = 1;
        for (const file of sortedFiles) {
            const filePath = path.join(migrationsDir, file);

            // Read the SQL content
            const sqlContent = fs.readFileSync(filePath, 'utf8');
            const lineCount = sqlContent.split('\n').length;

            console.log(`\n${count}. ${file}`);
            console.log(`   Path: ${filePath}`);
            console.log(`   Size: ${sqlContent.length} characters, ${lineCount} lines`);

            // Optionally show first few lines of SQL
            const preview = sqlContent.split('\n').slice(0, 3).join('\n   ');
            console.log(`   Preview: ${preview}${sqlContent.split('\n').length > 3 ? '...' : ''}`);

            count++;
        }

        console.log('\n========================================');
        console.log(`Total migration files to apply: ${sortedFiles.length}`);
        console.log('Note: This script only logs what would be applied.');
        console.log('To actually run migrations, you would need to connect to a database and execute the SQL.');
        console.log('========================================');

    } catch (error) {
        console.error('Error during migration:', error.message);
        process.exit(1);
    }
}

// Run the migration script if called directly
if (require.main === module) {
    runMigrations();
}

module.exports = { runMigrations };

