#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Define the migrations directory path
const migrationsDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');

/**
 * Reads DATABASE_URL from .env.test file
 * Returns the connection string or null if not found
 */
function readDatabaseUrl() {
    try {
        if (!fs.existsSync(envFilePath)) {
            console.warn(`Warning: Environment file not found at ${envFilePath}`);
            return null;
        }

        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (trimmedLine.startsWith('#') || trimmedLine.length === 0) {
                continue;
            }

            // Look for DATABASE_URL
            if (trimmedLine.startsWith('DATABASE_URL=')) {
                const dbUrl = trimmedLine.substring('DATABASE_URL='.length).trim();

                // Remove quotes if present
                return dbUrl.replace(/^["']|["']$/g, '');
            }
        }

        console.warn('Warning: DATABASE_URL not found in environment file');
        return null;

    } catch (error) {
        console.warn(`Warning: Failed to read environment file: ${error.message}`);
        return null;
    }
}

/**
 * Parses and logs database connection information
 */
function logDatabaseConnection(dbUrl) {
    if (!dbUrl) {
        console.log('Database connection: No DATABASE_URL found - running in dry-run mode');
        return false;
    }

    console.log('Database connection information:');

    try {
        // Parse the connection string
        const url = new URL(dbUrl);
        const protocol = url.protocol.replace(':', '');

        console.log(`  Protocol: ${protocol}`);
        console.log(`  Host: ${url.hostname}`);
        console.log(`  Port: ${url.port || (protocol === 'postgres' ? '5432' : 'default')}`);
        console.log(`  Database: ${url.pathname.substring(1)}`);

        // Log username (mask password)
        if (url.username) {
            console.log(`  Username: ${url.username}`);
            console.log(`  Password: [MASKED]`);
        }

        console.log(`\n✓ Successfully parsed DATABASE_URL from .env.test`);
        return true;

    } catch (error) {
        console.log(`  Raw URL: ${dbUrl.substring(0, 50)}${dbUrl.length > 50 ? '...' : ''}`);
        console.log(`  Note: Could not parse URL format: ${error.message}`);
        return false;
    }
}

