CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.ensureMigrationsDir();
    }

    /**
     * Ensure the migrations directory exists
     */
    ensureMigrationsDir() {
        if (!fs.existsSync(this.migrationsDir)) {
            console.log(`Creating migrations directory: ${this.migrationsDir}`);
            fs.mkdirSync(this.migrationsDir, { recursive: true });
        }
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Sorted array of migration file names
     */
    getMigrationFiles() {
        try {
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files
            const sqlFiles = files.filter(file => {
                return file.endsWith('.sql');
            });

            // Sort files numerically by their prefix
            sqlFiles.sort((a, b) => {
                const numA = parseInt(a.split('_')[0]) || 0;
                const numB = parseInt(b.split('_')[0]) || 0;
                return numA - numB;
            });

            return sqlFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Log migration files that would be applied
     */
    dryRun() {
        console.log('=== DATABASE MIGRATION DRY RUN ===');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log('');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found in the migrations directory.');
            console.log('Please add SQL files with naming convention: 001_descriptive_name.sql');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log('');

        migrationFiles.forEach((file, index) => {
            const filePath = path.join(this.migrationsDir, file);
            console.log(`${index + 1}. ${file}`);

            try {
                // Read a preview of the SQL content
                const content = fs.readFileSync(filePath, 'utf8');
                const preview = content.split('\n')[0].trim();

                if (preview) {
                    console.log(`   Preview: ${preview}`);
                }

                // Get file size
                const stats = fs.statSync(filePath);
                console.log(`   Size: ${stats.size} bytes`);
            } catch (error) {
                console.log(`   Error reading file: ${error.message}`);
            }

            console.log('');
        });

        console.log('=== DRY RUN COMPLETE ===');
        console.log(`To apply these migrations, you would need to:`);
        console.log(`1. Connect to your database`);
        console.log(`2. Read each SQL file`);
        console.log(`3. Execute the SQL statements`);
        console.log(`4. Track which migrations have been applied`);
    }

    /**
     * Display usage information
     */
    showUsage() {
        console.log('Database Migration Script');
        console.log('');
        console.log('Usage: node migrate.js [command]');
        console.log('');
        console.log('Commands:');
        console.log('  dry-run    List all migrations that would be applied (default)');
        console.log('  help       Show this help message');
        console.log('');
        console.log('Examples:');
        console.log('  node migrate.js             # List migrations');
        console.log('  node migrate.js dry-run     # Same as above');
        console.log('');
        console.log('Migration files should be placed in ./migrations/ directory');
        console.log('with naming convention: 001_descriptive_name.sql');
        console.log('');
    }
}

// Main execution
if (require.main === module) {
    const runner = new MigrationRunner();
    const command = process.argv[2] || 'dry-run';

    switch (command.toLowerCase()) {
        case 'dry-run':
