#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.envFile = path.join(__dirname, '.env.test');
    this.databaseUrl = null;
    this.ensureMigrationsDir();
    this.loadEnvironmentVariables();
  }

  /**
   * Load environment variables from .env.test file
   */
  loadEnvironmentVariables() {
    try {
      if (fs.existsSync(this.envFile)) {
        const envContent = fs.readFileSync(this.envFile, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
          const trimmedLine = line.trim();

          // Skip empty lines and comments
          if (!trimmedLine || trimmedLine.startsWith('#')) {
            continue;
          }

          // Parse key=value pairs
          const equalsIndex = trimmedLine.indexOf('=');
          if (equalsIndex !== -1) {
            const key = trimmedLine.substring(0, equalsIndex).trim();
            const value = trimmedLine.substring(equalsIndex + 1).trim();

            if (key === 'DATABASE_URL') {
              this.databaseUrl = value;
              break;
            }
          }
        }

        if (this.databaseUrl) {
          console.log(`✓ Loaded DATABASE_URL from ${this.envFile}`);
        } else {
          console.log(`⚠ DATABASE_URL not found in ${this.envFile}`);
        }
      } else {
        console.log(`⚠ Environment file not found: ${this.envFile}`);
      }
    } catch (error) {
      console.error(`Error reading environment file: ${error.message}`);
    }
  }

  /**
   * Parse and log database connection information
   */
  logDatabaseConnectionInfo() {
    if (!this.databaseUrl) {
      console.log('No DATABASE_URL available. Running in dry-log mode only.');
      return;
    }

    console.log('=== Database Connection Information ===');

    try {
      // Parse the database URL
      const url = new URL(this.databaseUrl);
      const protocol = url.protocol.replace(':', '');
      const hostname = url.hostname;
      const port = url.port || 'default';
      const database = url.pathname.substring(1); // Remove leading slash

      // Parse username and password
      const username = url.username || 'not specified';
      const password = url.password ? '***' + url.password.slice(-4) : 'not specified';

      console.log(`Protocol: ${protocol}`);
      console.log(`Host: ${hostname}`);
      console.log(`Port: ${port}`);
      console.log(`Database: ${database || 'not specified'}`);
      console.log(`Username: ${username}`);
      console.log(`Password: ${password}`);

      // Check for common database types
      let dbType = 'Unknown';
      if (protocol.includes('postgres')) {
        dbType = 'PostgreSQL';
      } else if (protocol.includes('mysql')) {
        dbType = 'MySQL';
      } else if (protocol.includes('sqlite')) {
        dbType = 'SQLite';
      } else if (protocol.includes('mongo')) {
        dbType = 'MongoDB';
      }

      console.log(`Database Type: ${dbType}`);

      // Log connection success message
      console.log('\n✓ Would connect to database successfully');
      console.log(`  Connection string: ${protocol}://${username}:${password.includes('***') ? '********' : password}@${hostname}:${port}/${database}`);

      // Add some warnings for common issues
      if (password === 'not specified') {
        console.log('⚠ Warning: No password specified in connection string');
      }

      if (hostname.includes('localhost') || hostname === '127.0.0.1') {
        console.log('ℹ Info: Connecting to local database');
      } else {
        console.log('ℹ Info: Connecting to remote database');
      }

    } catch (error) {
      console.error(`Error parsing DATABASE_URL: ${error.message}`);
      console.log(`Raw DATABASE_URL: ${this.databaseUrl.substring(0, 50)}...`);
    }

    console.log('=======================================\n');
  }

