      console.log(`Raw DATABASE_URL: ${this.databaseUrl.substring(0, 50)}...`);
    }

    console.log('=======================================\n');
  }

  /**
   * Ensure the migrations directory exists
   */
  ensureMigrationsDir() {
    if (!fs.existsSync(this.migrationsDir)) {
      console.log(`Creating migrations directory: ${this.migrationsDir}`);
      fs.mkdirSync(this.migrationsDir, { recursive: true });
    }
  }

  /**
   * Get all migration files from the migrations directory
   * @returns {Array} Array of migration file objects with name and path
   */
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and parse version numbers from filenames
      const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => {
          const filePath = path.join(this.migrationsDir, file);
          const version = this.extractVersionFromFileName(file);

          return {
            name: file,
            path: filePath,
            version: version,
            timestamp: this.extractTimestampFromFileName(file)
          };
        })
        .sort((a, b) => {
          // Sort by version if available, otherwise by timestamp, otherwise by name
          if (a.version !== null && b.version !== null) {
            return this.compareVersions(a.version, b.version);
          } else if (a.timestamp !== null && b.timestamp !== null) {
            return a.timestamp.localeCompare(b.timestamp);
          }
          return a.name.localeCompare(b.name);
        });

      return migrationFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Extract version number from filename
   * @param {string} filename - The migration filename
   * @returns {string|null} Version string or null if not found
   */
  extractVersionFromFileName(filename) {
    // Common patterns: v001_, 001_, V1_, etc.
    const versionMatch = filename.match(/(?:v|V)?(\d+)(?:_|-)/);
    if (versionMatch && versionMatch[1]) {
      return versionMatch[1];
    }
    return null;
  }

  /**
   * Extract timestamp from filename
   * @param {string} filename - The migration filename
   * @returns {string|null} Timestamp string or null if not found
   */
  extractTimestampFromFileName(filename) {
    // Common pattern: YYYYMMDDHHMMSS or similar
    const timestampMatch = filename.match(/(\d{14}|\d{8}_\d{6})/);
    if (timestampMatch) {
      return timestampMatch[1];
    }
    return null;
  }

  /**
   * Compare version strings
   * @param {string} v1 - First version
   * @param {string} v2 - Second version
   * @returns {number} Comparison result
   */
  compareVersions(v1, v2) {
    // Convert to numbers for comparison
    const num1 = parseInt(v1, 10);
    const num2 = parseInt(v2, 10);

    if (num1 < num2) return -1;
    if (num1 > num2) return 1;
    return 0;
  }

  /**
   * Log migration files in order
   */
  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Scanning migration files in: ${this.migrationsDir}`);
    console.log('---------------------------------\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found in the migrations directory.');
      console.log('Add SQL files to the migrations/ directory to see them listed here.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file.name}`);

      // Show additional info if available
      const infoParts = [];
      if (file.version !== null) {
        infoParts.push(`Version: v${file.version}`);
      }
      if (file.timestamp !== null) {
        infoParts.push(`Timestamp: ${file.timestamp}`);
      }

      if (infoParts.length > 0) {
        console.log(`   (${infoParts.join(', ')})`);
      }
    });

    console.log('\n=== Summary ===');
    console.log(`Total migrations to apply: ${migrationFiles.length}`);
    console.log('\nNote: This script only logs the migrations. To actually apply them,');
    console.log('you would need to read each SQL file and execute its contents.');
  }

  /**
   * Log what would be applied without actually applying
   */
  dryRun() {
    console.log('\n=== DRY RUN MODE ===');
    console.log('The following migrations would be applied:\n');

    const migrationFiles = this.getMigrationFiles();

    migrationFiles.forEach((file, index) => {
      console.log(`[${index + 1}] Would apply: ${file.name}`);

      try {
        const sqlContent = fs.readFileSync(file.path, 'utf8');
        const lines = sqlContent.split('\n').filter(line => line.trim());
        const preview = lines.length > 0 ? lines[0].substring(0, 80) : '(empty file)';
        console.log(`    Preview: ${preview}${preview.length >= 80 ? '...' : ''}`);
      } catch (error) {
        console.log(`    Error reading file: ${error.message}`);
      }
    });
  }
}

// Main execution
function main() {
  const args = process.argv.slice(2);
  const runner = new MigrationRunner();

  if (args.includes('--dry-run') || args.includes('-d')) {
    runner.dryRun();
  } else {
    runner.logMigrations();
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

