#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Test different connection string scenarios
const testScenarios = [
  {
    name: 'PostgreSQL with password',
    envContent: 'DATABASE_URL=postgres://user:password123@localhost:5432/mydb',
    expectedProtocol: 'postgres'
  },
  {
    name: 'MySQL without password',
    envContent: 'DATABASE_URL=mysql://root@localhost:3306/testdb',
    expectedProtocol: 'mysql'
  },
  {
    name: 'SQLite file',
    envContent: 'DATABASE_URL=sqlite:///path/to/database.sqlite',
    expectedProtocol: 'sqlite'
  },
  {
    name: 'Invalid URL',
    envContent: 'DATABASE_URL=not-a-valid-url',
    shouldError: true
  },
  {
    name: 'Empty file',
    envContent: '# Comment line\n',
    shouldWarn: true
  }
];

console.log('Testing connection string resolution scenarios:\n');

testScenarios.forEach((scenario, index) => {
  console.log(`Test ${index + 1}: ${scenario.name}`);
  console.log('='.repeat(50));

  // Create temporary env file
  const tempEnvFile = path.join(__dirname, `.env.test.${index}`);
  fs.writeFileSync(tempEnvFile, scenario.envContent);

  // Simulate the loadEnvironmentVariables logic
  try {
    if (fs.existsSync(tempEnvFile)) {
      const envContent = fs.readFileSync(tempEnvFile, 'utf8');
      const lines = envContent.split('\n');
      let databaseUrl = null;

      for (const line of lines) {
        const trimmedLine = line.trim();

        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex !== -1) {
          const key = trimmedLine.substring(0, equalsIndex).trim();
          const value = trimmedLine.substring(equalsIndex + 1).trim();

          if (key === 'DATABASE_URL') {
            databaseUrl = value;
            break;
          }
        }
