      const migrationFiles = sqlFiles.map(file => {
        const filePath = path.join(this.migrationsDir, file);
        const version = this.extractVersionFromFileName(file);
        const timestamp = this.extractTimestampFromFileName(file);

        return {
          name: file,
          path: filePath,
          version: version,
          timestamp: timestamp,
          sortKey: this.createSortKey(version, timestamp, file)
        };
      });

      // Sort by the computed sort key
      migrationFiles.sort((a, b) => a.sortKey.localeCompare(b.sortKey));

      return migrationFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Extract version number from filename
   */
  extractVersionFromFileName(filename) {
    const versionMatch = filename.match(/(?:v|V)?(\d+)(?:_|-)/);
    return versionMatch && versionMatch[1] ? versionMatch[1] : null;
  }

  /**
   * Extract timestamp from filename
   */
  extractTimestampFromFileName(filename) {
    const timestampMatch = filename.match(/(\d{14}|\d{8}_\d{6})/);
    return timestampMatch ? timestampMatch[1] : null;
  }

  /**
   * Create a sort key for consistent ordering
   */
  createSortKey(version, timestamp, filename) {
    // Priority: version > timestamp > filename
    if (version) {
      return `v${version.padStart(10, '0')}`;
    }
    if (timestamp) {
      return `t${timestamp}`;
    }
    return `f${filename}`;
  }

