        // Ignore stat errors
      }
    });

    console.log('\n=== Summary ===');
    console.log(`Total migrations to apply: ${migrationFiles.length}`);
    console.log('\nNote: This is a listing script only.');
    console.log('To execute migrations, extend this script with database connectivity.');
  }

  /**
   * Dry run with SQL preview
   */
  dryRun() {
    console.log('=== Migration Dry Run ===');
    console.log(`Scanning: ${this.migrationsDir}`);
    console.log('='.repeat(40) + '\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migrations to preview.');
      return;
    }

    migrationFiles.forEach((file, index) => {
      console.log(`[${index + 1}] ${file.name}`);

      try {
        const content = fs.readFileSync(file.path, 'utf8');
        const lines = content.split('\n')
          .map(line => line.trim())
          .filter(line => line && !line.startsWith('--'));

        if (lines.length > 0) {
          const firstStatement = lines[0];
