          console.log(`    SQL: ${preview}`);
        } else {
          console.log(`    (Empty or comment-only file)`);
        }
      } catch (error) {
        console.log(`    Error: ${error.message}`);
      }

      console.log(); // Blank line between migrations
    });
  }
}

// Main execution
function main() {
  const args = process.argv.slice(2);
  const runner = new MigrationRunner();

  if (args.includes('--dry-run') || args.includes('-d')) {
    runner.dryRun();
  } else if (args.includes('--help') || args.includes('-h')) {
    console.log('Usage: node migrate-simple.js [options]');
    console.log('\nOptions:');
    console.log('  --dry-run, -d    Show SQL previews');
    console.log('  --help, -h       Show this help message');
    console.log('\nWithout options: List migration files in order');
  } else {
    runner.logMigrations();
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

module.exports = MigrationRunner;

