#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */
class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = migrationsDir;
  }

  /**
   * Get all migration files from the migrations directory
   * @returns {Array} Sorted array of migration file names
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist`);
        process.exit(1);
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in', this.migrationsDir);
        return [];
      }

      // Sort files by name (assuming naming convention like 001_name.sql, 002_name.sql)
      const sortedFiles = sqlFiles.sort((a, b) => {
        // Extract numeric prefix if present
        const numA = this.extractNumberPrefix(a);
        const numB = this.extractNumberPrefix(b);

        if (numA !== null && numB !== null) {
          return numA - numB;
        }

        // Fallback to alphabetical sort
        return a.localeCompare(b);
      });

      return sortedFiles;
    } catch (error) {
      console.error('Error reading migrations directory:', error.message);
      process.exit(1);
    }
  }

  /**
   * Extract numeric prefix from filename
   * @param {string} filename 
   * @returns {number|null} Numeric prefix or null if not found
   */
  extractNumberPrefix(filename) {
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : null;
  }

  /**
   * Log migration files in order
   */
  logMigrations() {
    console.log('Database Migration Script');
    console.log('=========================');
    console.log(`Reading migrations from: ${this.migrationsDir}`);
    console.log();

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migrations to apply.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log();

    migrationFiles.forEach((file, index) => {
      const filePath = path.join(this.migrationsDir, file);
      console.log(`${index + 1}. ${file}`);

      // Optional: Show a preview of the SQL content
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const firstLine = content.split('\n')[0].trim();
        if (firstLine) {
          console.log(`   ${firstLine}`);
        }
      } catch (error) {
        console.log(`   [Error reading file: ${error.message}]`);
      }

      console.log();
    });

    console.log('Ready to apply migrations in the above order.');
  }

  /**
   * Main entry point
   */
  run() {
    this.logMigrations();
  }
}

// Run the migration script
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.run();
}

module.exports = MigrationRunner;

