 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

function readMigrations(migrationsDir) {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.log(`Migrations directory '${migrationsDir}' does not exist.`);
            console.log('No migrations to apply.');
            return [];
        }

        // Read all files in migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files (case-insensitive)
        const sqlFiles = files.filter(file => 
            file.toLowerCase().endsWith('.sql')
        );

        // Sort files in natural order (alphabetical, which works for timestamp-based names)
        // For more complex sorting, you could extract numeric prefixes
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return [];
    }
}

function logMigrations(migrationsDir, sqlFiles) {
    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found.');
        return;
