#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.migrations = [];
  }

  /**
   * Ensure migrations directory exists
   */
  ensureMigrationsDir() {
    if (!fs.existsSync(this.migrationsDir)) {
      fs.mkdirSync(this.migrationsDir, { recursive: true });
      console.log(`Created migrations directory: ${this.migrationsDir}`);
    }
  }

  /**
   * Discover and sort migration files
   */
  discoverMigrations() {
    this.ensureMigrationsDir();

    try {
      const files = fs.readdirSync(this.migrationsDir, { withFileTypes: true });

      // Filter for SQL files and extract metadata
      const migrationFiles = files
        .filter(file => file.isFile() && file.name.endsWith('.sql'))
        .map(file => {
          const filePath = path.join(this.migrationsDir, file.name);
          const stats = fs.statSync(filePath);

          return {
            filename: file.name,
            filepath: filePath,
            created: stats.birthtime,
            modified: stats.mtime,
            size: stats.size
          };
        });

      // Sort migrations by name (lexicographically)
      migrationFiles.sort((a, b) => a.filename.localeCompare(b.filename));

      this.migrations = migrationFiles;
      return migrationFiles;

    } catch (error) {
      if (error.code === 'ENOENT') {
        console.log(`No migrations directory found at: ${this.migrationsDir}`);
        return [];
      }
      throw error;
    }
  }

  /**
   * Log migration information in a formatted way
   */
  logMigrationInfo(migration, index, total) {
    const migrationNumber = (index + 1).toString().padStart(3, ' ');
    const sizeKB = (migration.size / 1024).toFixed(2);

    console.log(`╔══════════════════════════════════════════════════════════════╗`);
    console.log(`║ MIGRATION ${migrationNumber}/${total}`);
    console.log(`╠══════════════════════════════════════════════════════════════╣`);
    console.log(`║ Filename: ${migration.filename.padEnd(50)} ║`);
    console.log(`║ Path:     ${migration.filepath.padEnd(50)} ║`);
    console.log(`║ Size:     ${sizeKB} KB`.padEnd(59) + '║');
    console.log(`║ Created:  ${migration.created.toLocaleString()}`.padEnd(59) + '║');
    console.log(`╠══════════════════════════════════════════════════════════════╣`);
    console.log(`║ This file would be applied to the database.                 ║`);
    console.log(`╚══════════════════════════════════════════════════════════════╝`);
    console.log('');
  }

  /**
   * Preview migrations that would be applied
   */
  previewMigrations() {
    console.log('🔍 Discovering migrations...\n');

    const migrations = this.discoverMigrations();

    if (migrations.length === 0) {
      console.log('No migration files found in:', this.migrationsDir);
      console.log('To create a migration, add SQL files to the migrations directory:');
      console.log('  Example: 001_create_users_table.sql');
      console.log('  Example: 002_add_email_index.sql');
      return;
    }

    console.log(`📂 Found ${migrations.length} migration(s) in ${this.migrationsDir}`);
    console.log('📋 Migration execution order:');
    console.log('='.repeat(60));

    // Log summary of all migrations first
    migrations.forEach((migration, index) => {
      const prefix = `[${(index + 1).toString().padStart(3, '0')}]`;
      console.log(`${prefix} ${migration.filename}`);
    });

    console.log('='.repeat(60));
    console.log('\n📄 Detailed migration preview:\n');

    // Log detailed information for each migration
    migrations.forEach((migration, index) => {
      this.logMigrationInfo(migration, index, migrations.length);
    });

    console.log('🚀 Migration Summary:');
    console.log(`   • Total migrations: ${migrations.length}`);
    console.log(`   • Total size: ${(migrations.reduce((sum, m) => sum + m.size, 0) / 1024).toFixed(2)} KB`);
    console.log(`   • Ready to apply ${migrations.length} migration(s) in order shown above`);
  }

  /**
   * Read and display the content of a migration file
   */
  showMigrationContent(filename) {
    const filePath = path.join(this.migrationsDir, filename);

    try {
      if (fs.existsSync(filePath)) {
        console.log(`\n📄 Content of ${filename}:`);
        console.log('='.repeat(60));
        const content = fs.readFileSync(filePath, 'utf8');
        console.log(content);
        console.log('='.repeat(60));
      } else {
        console.log(`❌ Migration file not found: ${filename}`);
      }
    } catch (error) {
      console.log(`❌ Error reading migration file: ${error.message}`);
    }
  }
}

/**
 * Command line interface
 */
function main() {
  const runner = new MigrationRunner();

  // Parse command line arguments
  const args = process.argv.slice(2);

  if (args.length === 0) {
    // Default behavior: preview all migrations
    runner.previewMigrations();
  } else if (args[0] === '--help' || args[0] === '-h') {
    showHelp();
  } else if (args[0] === '--list' || args[0] === '-l') {
    // Just list migrations without detailed info
    const migrations = runner.discoverMigrations();
    console.log('Migration files (in execution order):');
    migrations.forEach((m, i) => {
      console.log(`  ${(i + 1).toString().padStart(3, '0')}. ${m.filename}`);
    });
  } else if (args[0] === '--show' || args[0] === '-s' && args[1]) {
    // Show content of a specific migration
    runner.showMigrationContent(args[1]);
  } else if (args[0] === '--count' || args[0] === '-c') {
    // Just show count
    const migrations = runner.discoverMigrations();
    console.log(`Total migration files: ${migrations.length}`);
  } else {
    console.log('Unknown option. Use --help for usage information.');
  }
}

function showHelp() {
  console.log(`
Database Migration Script

Usage:
  node migrate.js [options]

Options:
  (no options)        Preview all migrations with detailed information
  --help, -h          Show this help message
  --list, -l          List migration files in execution order
  --show <file>, -s   Show the content of a specific migration file
  --count, -c         Show the total count of migration files
  --path, -p          Show the migrations directory path

Examples:
  node migrate.js                 # Preview all migrations
  node migrate.js --list          # List migrations briefly
  node migrate.js --show 001_initial.sql  # Show content of a file
  node migrate.js --count         # Show total migration count

Migration Files:
  • Place SQL files in ./migrations/ directory
  • Files are executed in alphabetical order
  • Recommended naming: 001_<description>.sql, 002_<description>.sql, etc.
  `);
}

// Run the script if executed directly
if (require.main === module) {
  main();
}

module.exports = MigrationRunner;

-- Migration: 001_create_users_table.sql
-- Description: Create users table with basic fields
-- Created: 2024-01-01

CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  username VARCHAR(50) UNIQUE NOT NULL,
  email VARCHAR(100) UNIQUE NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Indexes for faster lookups
CREATE INDEX idx_users_username ON users(username);
CREATE INDEX idx_users_email ON users(email);

COMMENT ON TABLE users IS 'Stores user account information';
COMMENT ON COLUMN users.username IS 'Unique username for login';
COMMENT ON COLUMN users.email IS 'User email address for notifications';

-- Migration: 002_create_posts_table.sql
-- Description: Create posts table for blog/articles
-- Created: 2024-01-02

CREATE TABLE IF NOT EXISTS posts (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title VARCHAR(200) NOT NULL,
  content TEXT NOT NULL,
  status VARCHAR(20) DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  published_at TIMESTAMP NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Foreign key index for performance
CREATE INDEX idx_posts_user_id ON posts(user_id);
-- Index for status filtering
CREATE INDEX idx_posts_status ON posts(status);
-- Index for published posts retrieval
CREATE INDEX idx_posts_published ON posts(published_at) WHERE status = 'published';

COMMENT ON TABLE posts IS 'Blog posts or articles created by users';
COMMENT ON COLUMN posts.status IS 'Post status: draft, published, or archived';

-- Migration: 003_add_comments_table.sql
-- Description: Create comments table for post comments
-- Created: 2024-01-03

CREATE TABLE IF NOT EXISTS comments (
  id SERIAL PRIMARY KEY,
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  parent_id INTEGER NULL REFERENCES comments(id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Indexes for efficient querying
CREATE INDEX idx_comments_post_id ON comments(post_id);
CREATE INDEX idx_comments_user_id ON comments(user_id);
CREATE INDEX idx_comments_parent_id ON comments(parent_id);
-- Composite index for common queries
CREATE INDEX idx_comments_post_created ON comments(post_id, created_at DESC);

-- Add comments_count column to posts table
ALTER TABLE posts 
ADD COLUMN comments_count INTEGER DEFAULT 0;

COMMENT ON TABLE comments IS 'User comments on posts';
COMMENT ON COLUMN comments.parent_id IS 'For nested comments/replies';

-- Migration: 010_add_indexes_and_constraints.sql
-- Description: Add additional indexes and constraints for performance
-- Created: 2024-01-10

-- Add full-text search index for post content
CREATE INDEX idx_posts_content_gin ON posts USING gin(to_tsvector('english', content));

-- Add full-text search index for comment content
CREATE INDEX idx_comments_content_gin ON comments USING gin(to_tsvector('english', content));

-- Add unique constraint for user favorite posts (if we had such a table)
