/**
 * Read DATABASE_URL from .env.test file
 */
readDatabaseUrl() {
  try {
    if (fs.existsSync(this.envFile)) {
      const envContent = fs.readFileSync(this.envFile, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        const trimmedLine = line.trim();
        // Skip comments and empty lines
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Look for DATABASE_URL
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          this.databaseUrl = trimmedLine.substring('DATABASE_URL='.length);

          // Remove quotes if present
          this.databaseUrl = this.databaseUrl.replace(/^['"]|['"]$/g, '');

          console.log(`✅ Found DATABASE_URL in ${this.envFile}`);

          // Parse and mask the URL for logging
          const parsedUrl = this.parseDatabaseUrl(this.databaseUrl);
          this.logConnectionInfo(parsedUrl);

          return true;
        }
      }

      console.log(`⚠️  DATABASE_URL not found in ${this.envFile}`);
      return false;
    } else {
      console.log(`❌ ${this.envFile} file not found`);
      return false;
    }
  } catch (error) {
    console.log(`❌ Error reading ${this.envFile}: ${error.message}`);
    return false;
  }
}

/**
 * Parse database URL to extract connection details
 */
parseDatabaseUrl(url) {
  try {
    // Try to parse as a URL
    const parsed = new URL(url);

    // Extract username and password
    const username = parsed.username || 'unknown';
    const password = parsed.password ? '***' + parsed.password.slice(-4) : 'none';

    // Extract database name from pathname
    const database = parsed.pathname ? parsed.pathname.substring(1) : 'unknown';

    return {
      protocol: parsed.protocol.replace(':', ''),
      username: username,
      passwordMasked: password,
      host: parsed.hostname,
      port: parsed.port || '5432',
      database: database,
      fullUrlMasked: this.maskDatabaseUrl(url)
    };
  } catch (error) {
    // If URL parsing fails, return basic info
    return {
      protocol: 'unknown',
      username: 'unknown',
      passwordMasked: '***',
      host: 'unknown',
      port: 'unknown',
      database: 'unknown',
      fullUrlMasked: this.maskDatabaseUrl(url)
    };
  }
}

/**
 * Mask sensitive parts of the database URL for logging
 */
maskDatabaseUrl(url) {
  try {
    const parsed = new URL(url);
    if (parsed.password) {
      // Replace password with asterisks
      parsed.password = '********';
      return parsed.toString();
    }
    return url;
  } catch (error) {
    // Simple masking for non-URL strings
    return url.replace(/:[^:@]*@/, ':********@');
  }
}

/**
 * Log connection information (safely)
 */
logConnectionInfo(parsed) {
  console.log('🔌 Database Connection Information:');
  console.log('   ┌─────────────────────────────────────');
  console.log(`   │ Protocol: ${parsed.protocol}`);
  console.log(`   │ Host: ${parsed.host}:${parsed.port}`);
  console.log(`   │ Database: ${parsed.database}`);
  console.log(`   │ Username: ${parsed.username}`);
  console.log(`   │ Password: ${parsed.passwordMasked}`);
  console.log('   └─────────────────────────────────────');
  console.log(`   📍 Connection URL: ${parsed.fullUrlMasked}`);
  console.log('');
}

/**
 * Ensure migrations directory exists
 */
ensureMigrationsDir() {
  if (!fs.existsSync(this.migrationsDir)) {
    fs.mkdirSync(this.migrationsDir, { recursive: true });
    console.log(`Created migrations directory: ${this.migrationsDir}`);
  }
}

