      const envContent = fs.readFileSync(this.envFile, 'utf8');
      const envVars = this.parseEnvContent(envContent);

      // Store DATABASE_URL separately for convenience
      this.databaseUrl = envVars.DATABASE_URL || null;
      this.allEnvVars = envVars;

      if (this.databaseUrl) {
        console.log(`✅ Found DATABASE_URL in ${this.envFile}`);

        // Parse and mask the URL for logging
        const parsedUrl = this.parseDatabaseUrl(this.databaseUrl);
        this.logConnectionInfo(parsedUrl);

        return true;
      } else {
        console.log(`⚠️  DATABASE_URL not found in ${this.envFile}`);
        return false;
      }
    } else {
      console.log(`❌ ${this.envFile} file not found`);
      return false;
    }
  } catch (error) {
    console.log(`❌ Error reading ${this.envFile}: ${error.message}`);
    return false;
  }
}

/**
 * Parse .env file content into object
 */
parseEnvContent(content) {
  const envVars = {};
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmedLine = line.trim();

    // Skip comments and empty lines
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    // Parse key=value pairs
    const equalsIndex = trimmedLine.indexOf('=');
    if (equalsIndex > 0) {
      const key = trimmedLine.substring(0, equalsIndex);
      let value = trimmedLine.substring(equalsIndex + 1);

      // Remove surrounding quotes
      value = value.replace(/^['"]|['"]$/g, '');

      envVars[key] = value;
    }
  }

  return envVars;
}

