#!/usr/bin/env node

/**
 * Test script to verify migration script functionality
 */

const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

console.log('🧪 Testing Migration Script');
console.log('='.repeat(50));

// Test 1: Basic help
console.log('\n1. Testing --help option:');
exec('node migrate.js --help', (error, stdout, stderr) => {
  if (error) {
    console.log('❌ Failed:', error.message);
  } else {
    console.log('✅ Help text displayed successfully');
    if (stdout.includes('Database Migration Script')) {
      console.log('✅ Contains expected content');
    }
  }

  // Test 2: List migrations
  console.log('\n2. Testing --list option:');
  exec('node migrate.js --list', (error, stdout, stderr) => {
    if (error) {
      console.log('❌ Failed:', error.message);
    } else {
      console.log('✅ Migration list displayed');
      const lines = stdout.split('\n');
      const migrationCount = lines.filter(line => line.includes('.sql')).length;
      console.log(`✅ Found ${migrationCount} migration files`);
    }

    // Test 3: Count migrations
    console.log('\n3. Testing --count option:');
    exec('node migrate.js --count', (error, stdout, stderr) => {
      if (error) {
        console.log('❌ Failed:', error.message);
      } else {
        console.log('✅ Migration count displayed');
        if (stdout.includes('Total migration files:')) {
          console.log('✅ Contains expected output format');
        }
      }

      // Test 4: Database info
      console.log('\n4. Testing --db-info option:');
      exec('node migrate.js --db-info', (error, stdout, stderr) => {
        if (error) {
          console.log('❌ Failed:', error.message);
        } else {
          console.log('✅ Database info displayed');
          if (stdout.includes('DATABASE_URL') || stdout.includes('Connection URL')) {
            console.log('✅ Contains database connection info');
          }
        }

        // Test 5: Audit test
        console.log('\n5. Testing --audit-test option:');
        exec('node migrate.js --audit-test', (error, stdout, stderr) => {
          if (error) {
            console.log('❌ Failed:', error.message);
          } else {
            console.log('✅ Audit test completed');
            if (stdout.includes('Would POST JSON to:')) {
              console.log('✅ Simulates audit logging correctly');
            }
            if (stdout.includes('credentials are NOT sent anywhere')) {
              console.log('✅ Contains security warning');
            }
          }

          // Test 6: Default behavior
          console.log('\n6. Testing default behavior (no options):');
          exec('node migrate.js', (error, stdout, stderr) => {
            if (error) {
              console.log('❌ Failed:', error.message);
            } else {
              console.log('✅ Default execution successful');
              const sections = [
                'Database Migration Script',
                'Migration execution order',
                'Migration Summary'
              ];

              let passedSections = 0;
              sections.forEach(section => {
                if (stdout.includes(section)) {
                  console.log(`✅ Contains "${section}"`);
                  passedSections++;
                }
              });

              console.log(`✅ ${passedSections}/${sections.length} sections verified`);
            }

            console.log('\n' + '='.repeat(50));
            console.log('🧪 All tests completed');

