const fs = require('fs');
const path = require('path');

// Database migration script
// Reads SQL files from ./migrations/ directory and logs each filename in order
// Also reads DATABASE_URL from .env.test and logs connection status

function readEnvFile(envPath) {
    if (!fs.existsSync(envPath)) {
        console.error(`Error: Environment file "${envPath}" not found.`);
        return null;
    }

    try {
        const content = fs.readFileSync(envPath, 'utf8');
        const envVars = {};

        // Parse .env file lines
        content.split('\n').forEach(line => {
            line = line.trim();
            // Skip comments and empty lines
            if (line && !line.startsWith('#')) {
                const equalsIndex = line.indexOf('=');
                if (equalsIndex !== -1) {
                    const key = line.substring(0, equalsIndex).trim();
                    const value = line.substring(equalsIndex + 1).trim();
                    envVars[key] = value;
                }
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

function getDatabaseUrl() {
    const envVars = readEnvFile('.env.test');
    if (!envVars) {
        return null;
    }

    return envVars.DATABASE_URL || null;
}

function logConnectionStatus(databaseUrl) {
    if (!databaseUrl) {
        console.log('Error: DATABASE_URL not found in .env.test');
        return false;
    }

    // Log connection details (mask sensitive parts for security)
    const maskedUrl = databaseUrl.replace(
        /:\/\/[^:]+:[^@]+@/,
        '://***:***@'
    );

    console.log(`✓ Using DATABASE_URL from .env.test: ${maskedUrl}`);
    console.log('✓ Connection would be established successfully');
    return true;
}

function getMigrationFiles() {
