    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Directory "${migrationsDir}" not found.`);
        return null;
    }

    try {
        // Read all files from migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files (.sql extension)
        const sqlFiles = files.filter(file => file.toLowerCase().endsWith('.sql'));

        // Sort files alphabetically (which also handles numerical prefixes)
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return null;
    }
}

function logMigrationFiles(files) {
    console.log('\nMigration files to apply (in order):');
    console.log('=====================================');

    if (!files || files.length === 0) {
        console.log('No SQL files found.');
    } else {
        files.forEach(file => {
            console.log(`• ${file}`);
        });
        console.log(`\nTotal files: ${files.length}`);
    }
}

// Main execution
function main() {
    console.log('Database Migration Script');
    console.log('=========================\n');

    // 1. Read and log database connection status
    const databaseUrl = getDatabaseUrl();
    const connected = logConnectionStatus(databaseUrl);

    if (!connected) {
        console.log('\n⚠️  Cannot proceed without database connection.');
        process.exit(1);
    }

