#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationScanner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = path.resolve(migrationsDir);
        this.migrations = [];
    }

    scan() {
        this.#ensureDirectoryExists();
        this.#readMigrationFiles();
        this.#sortMigrations();
        return this.migrations;
    }

    #ensureDirectoryExists() {
        if (!fs.existsSync(this.migrationsDir)) {
            throw new Error(`Migrations directory "${this.migrationsDir}" not found.`);
        }
    }

    #readMigrationFiles() {
        try {
            const files = fs.readdirSync(this.migrationsDir);

            this.migrations = files
                .filter(file => file.endsWith('.sql'))
                .map(filename => {
                    const filePath = path.join(this.migrationsDir, filename);
                    const stats = fs.statSync(filePath);

                    let firstLine = '';
                    try {
                        const content = fs.readFileSync(filePath, 'utf8');
                        firstLine = content.split('\n')[0].trim();
                    } catch (err) {
                        // Continue without preview
                    }

                    return {
                        filename,
                        filePath,
                        size: stats.size,
                        created: stats.birthtime,
                        modified: stats.mtime,
                        firstLine
                    };
                });
        } catch (error) {
            throw new Error(`Failed to read migrations directory: ${error.message}`);
        }
    }

    #sortMigrations() {
        // Try to sort by numeric prefix first (e.g., 001_, 002_)
        this.migrations.sort((a, b) => {
            const numA = this.#extractPrefixNumber(a.filename);
            const numB = this.#extractPrefixNumber(b.filename);

            if (numA !== null && numB !== null) {
                return numA - numB;
            }

            // Fall back to alphabetical sorting
            return a.filename.localeCompare(b.filename);
        });
    }

    #extractPrefixNumber(filename) {
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : null;
    }

    printReport() {
        if (this.migrations.length === 0) {
            console.log('📭 No SQL migration files found in', this.migrationsDir);
            console.log('   Files should have .sql extension (e.g., 001_create_users.sql)');
            return;
        }

        console.log('🚀 Database Migration Scanner');
        console.log('='.repeat(60));
        console.log(`📁 Directory: ${this.migrationsDir}`);
