#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * that would be applied, in order.
 */

class MigrationRunner {
    constructor(migrationDir = './migrations') {
        this.migrationDir = migrationDir;
    }

    /**
     * Get all migration files from the migrations directory
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationDir)) {
                console.error(`Error: Migrations directory '${this.migrationDir}' does not exist.`);
                process.exit(1);
            }

            // Read all files from the migrations directory
            const files = fs.readdirSync(this.migrationDir)
                .filter(file => file.endsWith('.sql'))
                .sort() // Sort alphabetically to ensure order
                .map(file => ({
                    name: file,
                    path: path.join(this.migrationDir, file)
                }));

            if (files.length === 0) {
                console.log(`No .sql migration files found in '${this.migrationDir}'.`);
            }

            return files;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Validate migration file names follow a consistent naming pattern
     * @param {Array} files - Array of migration file objects
     * @returns {boolean} True if all files follow naming pattern
     */
    validateMigrationNames(files) {
        const pattern = /^\d{3,}_[a-z0-9_]+\.sql$/i;

        for (const file of files) {
            if (!pattern.test(file.name)) {
                console.warn(`Warning: Migration file '${file.name}' doesn't follow recommended naming pattern (001_descriptive_name.sql)`);
            }
        }
        return true;
    }

    /**
     * Log migration files that would be applied
     * @param {Array} files - Array of migration file objects
     */
    logMigrations(files) {
        console.log('\n📋 Database Migration Script');
        console.log('='.repeat(50));
        console.log(`Reading migration files from: ${path.resolve(this.migrationDir)}`);
        console.log(`Found ${files.length} migration file(s):\n`);

        files.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);

            // Optional: Show a preview of the SQL content
            try {
                const content = fs.readFileSync(file.path, 'utf8');
                const lines = content.split('\n');
                const firstLine = lines[0].trim();
                const preview = firstLine.length > 50 
                    ? firstLine.substring(0, 47) + '...' 
                    : firstLine;

                console.log(`   📄 Preview: ${preview}`);
            } catch (error) {
                console.log(`   ❌ Error reading file: ${error.message}`);
            }

            console.log();
        });

        console.log('='.repeat(50));
        console.log(`Total migrations to apply: ${files.length}`);
        console.log(`Note: This is a dry run. No actual database changes were made.`);
    }

    /**
     * Run the migration script
     */
    run() {
        console.log('🚀 Starting migration scan...\n');

        const files = this.getMigrationFiles();

        if (files.length === 0) {
            return;
        }

        this.validateMigrationNames(files);
        this.logMigrations(files);
    }
}

// Main execution
if (require.main === module) {
    const args = process.argv.slice(2);
    const migrationDir = args[0] || './migrations';

    const migrator = new MigrationRunner(migrationDir);
    migrator.run();
}

module.exports = MigrationRunner;

