/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            console.log('No migrations to apply.');
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files (files ending with .sql)
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log(`No SQL files found in '${MIGRATIONS_DIR}' directory.`);
            return [];
        }

        // Sort files alphabetically (which will apply migrations in order)
        // Common practice: use timestamp or sequence numbers in filenames
        const sortedFiles = sqlFiles.sort();

        return sortedFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return [];
    }
}

function logMigrations(migrations) {
    if (migrations.length === 0) {
        console.log('No migrations to apply.');
        return;
