    console.log(`Found ${migrations.length} migration(s) to apply:`);
    console.log('='.repeat(50));

    migrations.forEach((migration, index) => {
        const migrationPath = path.join(MIGRATIONS_DIR, migration);
        console.log(`[${index + 1}] ${migrationPath}`);
    });

    console.log('='.repeat(50));
    console.log(`Total migrations to apply: ${migrations.length}`);
}

