#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

async function runMigrations() {
    console.log('Starting migration process...\n');

    // Check if migrations directory exists
    const migrationsDir = path.join(__dirname, 'migrations');

    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${migrationsDir}`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log('Please add SQL migration files to the migrations/ directory.');
        return;
    }

    // Read all files in the migrations directory
    let migrationFiles;
    try {
        migrationFiles = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return;
    }

    // Filter for SQL files and sort them
    const sqlFiles = migrationFiles
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
            // Sort by filename (alphabetical order)
            // This ensures migrations are applied in a consistent order
            return a.localeCompare(b);
        });

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in migrations/ directory.');
        console.log('Please add .sql files to the migrations/ directory.');
        return;
    }

    console.log(`Found ${sqlFiles.length} SQL migration file(s):\n`);

    // Log each migration file in order
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);

        // Optional: Read and log a preview of the SQL content
        try {
            const filePath = path.join(migrationsDir, file);
            const stats = fs.statSync(filePath);
            console.log(`   Size: ${stats.size} bytes`);
            console.log(`   Path: ${filePath}`);

            // Read first few lines of the SQL file
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLine = content.split('\n')[0].trim();
            if (firstLine) {
                console.log(`   Preview: ${firstLine.substring(0, 100)}${firstLine.length > 100 ? '...' : ''}`);
            }
        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
        }

        console.log(); // Empty line between migrations
    });

    console.log(`\nMigration summary:`);
    console.log(`Total migrations to apply: ${sqlFiles.length}`);
    console.log(`\nTo apply these migrations, you would:`);
    console.log(`1. Read each SQL file`);
    console.log(`2. Execute the SQL commands against your database`);
    console.log(`3. Track which migrations have been applied (using a migrations table)`);

    // Return the list of migration files for potential further processing
    return sqlFiles;
}

// Helper function to validate filenames (optional)
function validateMigrationFilename(filename) {
    const validPattern = /^\d{14}_[a-zA-Z0-9_]+\.sql$/; // Example: 20240101000000_create_users_table.sql
    if (!validPattern.test(filename)) {
        console.warn(`Warning: Filename "${filename}" doesn't follow recommended timestamp naming convention`);
        console.warn('Recommended format: YYYYMMDDHHMMSS_description.sql');
    }
    return true;
}

// Run the migration script
if (require.main === module) {
    runMigrations().catch(error => {
        console.error('Migration failed:', error);
        process.exit(1);
    });
}

// Export for testing or programmatic use
module.exports = { runMigrations };

