#!/usr/bin/env node

/**
 * Advanced Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Supports multiple sorting strategies.
 */

const fs = require('fs');
const path = require('path');

async function runMigrations(options = {}) {
    const {
        sortBy = 'filename', // 'filename', 'timestamp', 'natural'
        verbose = false,
        previewLines = 1
    } = options;

    console.log('Starting migration process...\n');
    console.log(`Sorting strategy: ${sortBy}`);

    // Check if migrations directory exists
    const migrationsDir = path.join(__dirname, 'migrations');

    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${migrationsDir}`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log('Please add SQL migration files to the migrations/ directory.');
        return [];
    }

    // Read all files in the migrations directory
    let migrationFiles;
    try {
        migrationFiles = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return [];
    }

    // Filter for SQL files
    const sqlFiles = migrationFiles.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in migrations/ directory.');
        return [];
    }

    // Sort migration files based on selected strategy
    const sortedFiles = sortMigrationFiles(sqlFiles, sortBy);

    console.log(`Found ${sortedFiles.length} SQL migration file(s):\n`);

    // Log each migration file in order
    const results = [];
    sortedFiles.forEach((file, index) => {
        const result = {
            filename: file,
            order: index + 1,
            details: {}
        };

        console.log(`${index + 1}. ${file}`);

        try {
            const filePath = path.join(migrationsDir, file);
            const stats = fs.statSync(filePath);
            result.details.size = stats.size;
            result.details.path = filePath;

            if (verbose) {
                console.log(`   Size: ${stats.size} bytes`);
                console.log(`   Path: ${filePath}`);

                // Read and preview SQL content
                const content = fs.readFileSync(filePath, 'utf8');
                const lines = content.split('\n').slice(0, previewLines);
                lines.forEach((line, lineIndex) => {
                    const trimmedLine = line.trim();
                    if (trimmedLine) {
                        console.log(`   Line ${lineIndex + 1}: ${trimmedLine.substring(0, 80)}${trimmedLine.length > 80 ? '...' : ''}`);
                    }
                });
            }

            // Extract timestamp if present
            const timestampMatch = file.match(/^(\d{14})_/);
            if (timestampMatch) {
                const timestamp = timestampMatch[1];
                const date = new Date(
                    timestamp.substring(0, 4),    // year
                    timestamp.substring(4, 6) - 1, // month (0-indexed)
                    timestamp.substring(6, 8),    // day
                    timestamp.substring(8, 10),   // hour
                    timestamp.substring(10, 12),  // minute
                    timestamp.substring(12, 14)   // second
                );
                result.details.timestamp = date.toISOString();
                if (verbose) {
                    console.log(`   Timestamp: ${date.toISOString()}`);
                }
            }

        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
            result.error = error.message;
        }

        console.log(); // Empty line between migrations
        results.push(result);
    });

    console.log(`\nMigration summary:`);
    console.log(`Total migrations found: ${sortedFiles.length}`);
    console.log(`Sorting method: ${sortBy}`);

    if (sortedFiles.length > 0) {
        console.log(`\nFirst migration: ${sortedFiles[0]}`);
        console.log(`Last migration: ${sortedFiles[sortedFiles.length - 1]}`);
    }

    console.log(`\nTo apply these migrations, you would:`);
    console.log(`1. Connect to your database`);
    console.log(`2. Read each SQL file in the order shown above`);
    console.log(`3. Execute the SQL commands sequentially`);
    console.log(`4. Track applied migrations in a database table`);
    console.log(`5. Handle rollbacks if any migration fails`);

    return results;
}

/**
 * Sort migration files based on selected strategy
 */
function sortMigrationFiles(files, strategy) {
    switch (strategy) {
        case 'timestamp':
            // Sort by embedded timestamp in filename (YYYYMMDDHHMMSS)
            return files.sort((a, b) => {
                const timestampA = extractTimestamp(a);
                const timestampB = extractTimestamp(b);

                // Files with timestamps come before files without timestamps
                if (timestampA && timestampB) {
                    return timestampA.localeCompare(timestampB);
                } else if (timestampA && !timestampB) {
                    return -1; // a comes first
                } else if (!timestampA && timestampB) {
                    return 1; // b comes first
                } else {
                    // Both lack timestamps, fall back to filename sort
                    return a.localeCompare(b);
                }
            });

        case 'natural':
            // Natural sort (1, 2, 10 instead of 1, 10, 2)
            return files.sort((a, b) => {
                return naturalCompare(a, b);
            });

        case 'filename':
        default:
            // Simple alphabetical sort
            return files.sort((a, b) => a.localeCompare(b));
    }
}

/**
 * Extract timestamp from filename (format: YYYYMMDDHHMMSS_filename.sql)
 */
function extractTimestamp(filename) {
    const match = filename.match(/^(\d{14})_/);
    return match ? match[1] : null;
}

/**
 * Natural string comparison
 */
function naturalCompare(a, b) {
    const regex = /(\d+)|(\D+)/g;
    const aParts = a.match(regex) || [];
    const bParts = b.match(regex) || [];

    for (let i = 0; i < Math.min(aParts.length, bParts.length); i++) {
        const aPart = aParts[i];
        const bPart = bParts[i];

        // If both parts are numbers, compare numerically
        if (!isNaN(aPart) && !isNaN(bPart)) {
            const numA = parseInt(aPart, 10);
            const numB = parseInt(bPart, 10);
            if (numA !== numB) {
                return numA - numB;
            }
        } else {
            // Compare as strings
            if (aPart !== bPart) {
                return aPart.localeCompare(bPart);
            }
        }
    }

    // If all compared parts are equal, shorter string comes first
    return a.length - b.length;
}

/**
 * Validate migration filenames and suggest improvements
 */
function validateFilenames(files) {
    console.log('\nFilename validation:');
    let issues = 0;

    files.forEach((file, index) => {
        const timestamp = extractTimestamp(file);
        const hasUnderscore = file.includes('_');
        const hasValidExtension = file.endsWith('.sql');

        if (!hasValidExtension) {
            console.log(`  ❌ ${index + 1}. ${file} - Not a .sql file`);
