const fs = require('fs');
const path = require('path');

// Function to read DATABASE_URL from .env.test
function readDatabaseUrl() {
    try {
        const envPath = path.join(__dirname, '.env.test');
        if (fs.existsSync(envPath)) {
            const envContent = fs.readFileSync(envPath, 'utf8');
            const match = envContent.match(/DATABASE_URL=([^\n]+)/);
            if (match) {
                return match[1];
            }
        }
    } catch (error) {
        // Silently fail, will handle in runMigrations
    }
    return null;
}

// Function to mask sensitive parts of database URL for logging
function maskDatabaseUrl(url) {
    if (!url) return null;
    // Mask password in connection string
    return url.replace(/:[^:@]*@/, ':****@');
}

async function runMigrations(options = {}) {
    const {
        sortBy = 'filename', // 'filename', 'timestamp', 'natural'
        verbose = false,
        previewLines = 1,
        checkDatabase = true
    } = options;

    console.log('Starting migration process...\n');
    console.log(`Sorting strategy: ${sortBy}`);

    // Read and log database connection info
    let databaseUrl = null;
    let databaseInfo = {};

    if (checkDatabase) {
        databaseUrl = readDatabaseUrl();
        if (databaseUrl) {
            databaseInfo.available = true;
            databaseInfo.maskedUrl = maskDatabaseUrl(databaseUrl);

            // Parse database type from URL
            const urlMatch = databaseUrl.match(/^([^:]+):/);
            if (urlMatch) {
                databaseInfo.type = urlMatch[1];
            }

            console.log(`✓ Database connection configured`);
            if (verbose) {
                console.log(`  URL: ${databaseInfo.maskedUrl}`);
                console.log(`  Type: ${databaseInfo.type || 'Unknown'}`);
            }
        } else {
            databaseInfo.available = false;
            console.log(`⚠️  Database connection not configured`);
            if (verbose) {
                console.log(`  Reason: DATABASE_URL not found in .env.test or file missing`);
            }
        }
    }

    // Check if migrations directory exists
    const migrationsDir = path.join(__dirname, 'migrations');

    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${migrationsDir}`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log('Please add SQL migration files to the migrations/ directory.');
        return [];
    }

    // Read all files in the migrations directory
    let migrationFiles;
