        return [];
    }

    // Sort migration files based on selected strategy
    const sortedFiles = sortMigrationFiles(sqlFiles, sortBy);

    console.log(`Found ${sortedFiles.length} SQL migration file(s):\n`);

    // Log each migration file in order
    const results = [];
    sortedFiles.forEach((file, index) => {
        const result = {
            filename: file,
