});

// Test reading DATABASE_URL from a custom file
console.log('\n=== Testing Custom .env File Reading ===\n');

// Create a test .env file
const fs = require('fs');
const path = require('path');
const testEnvPath = path.join(__dirname, '.env.test.custom');

const testEnvContent = `# Custom test environment
DATABASE_URL=mysql://testuser:testpass123@testhost:3306/testdb
OTHER_VAR=value
ANOTHER_KEY=another_value`;

fs.writeFileSync(testEnvPath, testEnvContent);

// Temporarily rename original .env.test
const originalEnvPath = path.join(__dirname, '.env.test');
const backupEnvPath = path.join(__dirname, '.env.test.backup');

if (fs.existsSync(originalEnvPath)) {
    fs.renameSync(originalEnvPath, backupEnvPath);
}

// Move custom file to .env.test
fs.renameSync(testEnvPath, originalEnvPath);

// Test reading
console.log('Reading from custom .env.test:');
const customUrl = migrateAdvanced.readDatabaseUrl();
console.log(`Read URL: ${customUrl ? 'Yes' : 'No'}`);
if (customUrl) {
    const masked = migrateAdvanced.maskDatabaseUrl(customUrl);
    console.log(`Original: ${customUrl}`);
    console.log(`Masked: ${masked}`);
}

// Restore original
if (fs.existsSync(backupEnvPath)) {
    fs.renameSync(originalEnvPath, '.env.test.custom.tmp');
    fs.renameSync(backupEnvPath, originalEnvPath);
    fs.unlinkSync('.env.test.custom.tmp');
}

console.log('\n=== Testing Database Type Detection ===\n');

const typeTestUrls = [
    'postgres://host/db',
    'mysql://host/db',
    'mongodb://host/db',
    'redis://host/db',
    'sqlite://file.db',
    'invalid://host/db',
];

typeTestUrls.forEach(url => {
    const typeMatch = url.match(/^([^:]+):/);
    console.log(`${url}: ${typeMatch ? typeMatch[1] : 'Unknown type'}`);
});

console.log('\n=== Testing with Different .env Configurations ===\n');

// Test various .env file scenarios
const scenarios = [
    {
        name: 'Empty .env file',
        content: '# Empty file\n'
    },
    {
        name: '.env with comments only',
        content: '# DATABASE_URL=commented_out_value\n# ANOTHER=value\n'
    },
    {
        name: '.env with DATABASE_URL at end',
        content: 'API_KEY=test\nDATABASE_URL=postgres://test@localhost/db\n'
    },
    {
        name: '.env with DATABASE_URL in middle',
        content: 'FIRST=1\nDATABASE_URL=mysql://test@localhost/db\nLAST=2\n'
    },
    {
        name: '.env with spaces around equals',
        content: 'DATABASE_URL = postgres://test@localhost/db\n'
    },
    {
        name: '.env with quotes',
        content: 'DATABASE_URL="postgres://test@localhost/db"\n'
    }
];

scenarios.forEach((scenario, index) => {
    console.log(`\n${index + 1}. ${scenario.name}`);

    // Write test file
    const testPath = path.join(__dirname, `.env.test.scenario${index}`);
    fs.writeFileSync(testPath, scenario.content);

    // Read and parse
    try {
        const envContent = fs.readFileSync(testPath, 'utf8');
        const match = envContent.match(/DATABASE_URL\s*=\s*([^\n]+)/);
        if (match) {
            let url = match[1].trim();
            // Remove quotes if present
            url = url.replace(/^["']|["']$/g, '');
            console.log(`   Found URL: ${url}`);

            // Test masking
            const masked = migrateAdvanced.maskDatabaseUrl(url);
            console.log(`   Masked: ${masked}`);
