            console.log(`   No DATABASE_URL found`);
        }
    } catch (error) {
        console.log(`   Error: ${error.message}`);
    }

    // Clean up
    fs.unlinkSync(testPath);
});

console.log('\n=== Test Complete ===');

#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * ORIGINAL TASK: Write a database migration script migrate.js that reads SQL files 
 * from a ./migrations/ directory and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

async function runMigrations() {
    console.log('Starting migration process...\n');

    // Check if migrations directory exists
    const migrationsDir = path.join(__dirname, 'migrations');

    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${migrationsDir}`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log('Please add SQL migration files to the migrations/ directory.');
        return;
    }

    // Read all files in the migrations directory
    let migrationFiles;
    try {
        migrationFiles = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return;
    }

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = migrationFiles
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => a.localeCompare(b));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in migrations/ directory.');
        console.log('Please add .sql files to the migrations/ directory.');
        return;
    }

    console.log(`Found ${sqlFiles.length} SQL migration file(s):\n`);

    // Log each migration file in order
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nMigration summary:`);
    console.log(`Total migrations to apply: ${sqlFiles.length}`);
    console.log(`Migration order determined by: Alphabetical filename sorting`);

    // Return the list of migration files for potential further processing
    return sqlFiles;
}

// Run the migration script
if (require.main === module) {
    runMigrations().catch(error => {
        console.error('Migration failed:', error);
        process.exit(1);
    });
}

// Export for testing or programmatic use
module.exports = { runMigrations };

