#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in migration order.
 * 
 * Migration files are expected to be named with a numeric prefix
 * for ordering (e.g., 001_create_table.sql, 002_alter_table.sql).
 */

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all migration files in the migrations directory, sorted by name
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist.`);
                process.exit(1);
            }

            // Read all files from the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log(`No SQL migration files found in '${this.migrationsDir}'.`);
                return [];
            }

            // Sort files alphabetically (which will also sort numerically prefixed files)
            const sortedFiles = sqlFiles.sort();

            // Create array of migration objects
            const migrations = sortedFiles.map(file => ({
                name: file,
                path: path.join(this.migrationsDir, file),
                order: this.extractMigrationNumber(file)
            }));

            return migrations;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Extract migration number from filename
     * @param {string} filename - Migration filename
     * @returns {number|null} Migration number or null if not found
     */
    extractMigrationNumber(filename) {
        // Try to extract numeric prefix (e.g., "001" from "001_create_users.sql")
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('=== Database Migration Script ===\n');
        console.log(`Reading migration files from: ${this.migrationsDir}\n`);

        const migrations = this.getMigrationFiles();

        if (migrations.length === 0) {
            console.log('No migrations to apply.');
            return;
        }

        console.log(`Found ${migrations.length} migration file(s):\n`);

        // Log each migration file with its position
        migrations.forEach((migration, index) => {
            const number = (index + 1).toString().padStart(3, '0');
            console.log(`${number}. ${migration.name}`);

            // Log the migration number if extracted
            if (migration.order !== null) {
                console.log(`   Migration number: ${migration.order}`);
            }

            // Optionally show a preview of the SQL content
            try {
                const content = fs.readFileSync(migration.path, 'utf8');
                const preview = content.split('\n')[0].trim();
                if (preview) {
                    console.log(`   Preview: ${preview}...`);
                }
            } catch (error) {
                // Silently continue if we can't read the file
            }

            console.log(); // Empty line for readability
        });

        console.log('All migration files listed above would be applied in this order.');
        console.log('\nTo actually apply these migrations, you would:');
        console.log('1. Connect to your database');
        console.log('2. Read each SQL file');
        console.log('3. Execute the SQL statements');
        console.log('4. Track which migrations have been applied');
    }

    /**
     * Main function to run the migration logging
     */
    run() {
        this.logMigrations();
    }
}

// Parse command line arguments
const args = process.argv.slice(2);
let migrationsDir = './migrations';

// Allow specifying a custom migrations directory
if (args.length > 0) {
    if (args[0] === '--help' || args[0] === '-h') {
        console.log(`
Database Migration Script

Usage:
  node migrate.js [migrations-directory]

Options:
  [migrations-directory]  Path to migrations directory (default: ./migrations)
  --help, -h              Show this help message

Example:
  node migrate.js
  node migrate.js ./db-migrations

This script reads SQL files from the specified directory and logs them in order.
        `);
        process.exit(0);
    } else {
        migrationsDir = args[0];
    }
}

// Create and run the migration runner
const runner = new MigrationRunner(migrationsDir);
runner.run();

