     * Load environment variables from .env.test file
     */
    loadEnvironment() {
        try {
            // Check if the environment file exists
            if (!fs.existsSync(this.envFile)) {
                console.warn(`Warning: Environment file '${this.envFile}' not found.`);
                console.warn('Proceeding without database connection configuration.\n');
                return;
