                if (!line || line.startsWith('#')) {
                    return;
                }

                // Parse key=value
                const equalsIndex = line.indexOf('=');
                if (equalsIndex !== -1) {
                    const key = line.substring(0, equalsIndex).trim();
                    const value = line.substring(equalsIndex + 1).trim();
                    envVars[key] = value;
                }
            });

            // Get DATABASE_URL
            this.databaseUrl = envVars['DATABASE_URL'];

            if (!this.databaseUrl) {
                console.warn(`Warning: DATABASE_URL not found in '${this.envFile}'.`);
