const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

function readMigrations(migrationsDir) {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Migrations directory "${migrationsDir}" does not exist.`);
            process.exit(1);
        }

        // Read all files from the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract numeric prefixes for sorting
                const numA = parseInt(a.match(/^(\d+)/)?.[1] || 0);
                const numB = parseInt(b.match(/^(\d+)/)?.[1] || 0);
                return numA - numB;
            });

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

function logMigrations(migrations, migrationsDir) {
