#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Sorted array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Migrations directory not found: ${this.migrationsDir}`);
                console.log('Creating migrations directory...');
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                console.log('No migration files to process.');
                return [];
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log('No SQL migration files found in migrations directory.');
                return [];
            }

            // Sort files naturally (alphabetical/numerical)
            sqlFiles.sort();

            // Create file objects with full path
            const migrationFiles = sqlFiles.map(file => ({
                name: file,
                path: path.join(this.migrationsDir, file)
            }));

            return migrationFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Read and return the content of a migration file
     * @param {Object} migrationFile - Migration file object with path property
     * @returns {string} Content of the migration file
     */
    readMigrationContent(migrationFile) {
        try {
            return fs.readFileSync(migrationFile.path, 'utf8');
        } catch (error) {
            console.error(`Error reading migration file ${migrationFile.name}: ${error.message}`);
            return '';
        }
    }

    /**
     * Log migration information
     * @param {Object} migrationFile - Migration file object
     * @param {string} content - Migration SQL content
     * @param {number} index - Index in the migration sequence
     */
    logMigration(migrationFile, content, index) {
        console.log(`[${index + 1}] Migration: ${migrationFile.name}`);
        console.log(`   Path: ${migrationFile.path}`);

        // Count lines of SQL (excluding comments and empty lines)
        const sqlLines = content.split('\n')
            .filter(line => line.trim() && !line.trim().startsWith('--'))
            .length;
        console.log(`   SQL Statements: ${sqlLines}`);

        // Show first few lines of SQL content for context
        const previewLines = content.split('\n').slice(0, 3).join('\n   ');
        if (previewLines) {
            console.log(`   Preview:\n   ${previewLines}`);
            if (content.split('\n').length > 3) {
                console.log('   ...');
            }
        }
        console.log('');
    }

    /**
     * Run the migration process (dry-run mode - only logs)
     */
    run() {
        console.log('========================================');
        console.log('DATABASE MIGRATION DRY RUN');
        console.log('========================================\n');
        console.log(`Reading migrations from: ${this.migrationsDir}\n`);

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migrations to apply.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):\n`);

        // Process each migration file in order
        migrationFiles.forEach((migrationFile, index) => {
            const content = this.readMigrationContent(migrationFile);
            this.logMigration(migrationFile, content, index);
        });

        console.log('========================================');
        console.log('SUMMARY');
        console.log('========================================');
        console.log(`Total migrations to apply: ${migrationFiles.length}`);
        console.log('');
        console.log('NOTE: This is a dry run. No actual database operations were performed.');
        console.log('To apply migrations, implement database connection logic.');
        console.log('========================================\n');
    }
}

// If this script is run directly (not imported as a module)
if (require.main === module) {
    const runner = new MigrationRunner();
    runner.run();
}

module.exports = MigrationRunner;

