 * Read and parse .env.test file for DATABASE_URL
 * @returns {string|null} The DATABASE_URL or null if not found
 */
function getDatabaseUrl() {
    try {
        if (!fs.existsSync(envFile)) {
            console.log(`Environment file not found: ${envFile}`);
            return null;
        }

        const envContent = fs.readFileSync(envFile, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Look for DATABASE_URL
            if (trimmedLine.startsWith('DATABASE_URL=')) {
                const url = trimmedLine.substring('DATABASE_URL='.length).trim();
                // Remove quotes if present
                return url.replace(/^['"]|['"]$/g, '');
            }
        }

        console.log('DATABASE_URL not found in .env.test');
        return null;
    } catch (error) {
        console.error(`Error reading .env.test: ${error.message}`);
        return null;
    }
}

/**
 * Parse database URL to extract connection details
 * @param {string} databaseUrl - The database connection URL
 * @returns {Object} Parsed connection details
 */
function parseDatabaseUrl(databaseUrl) {
    try {
        // Parse PostgreSQL URL format: postgres://user:password@host:port/database
        const urlPattern = /^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
        const match = databaseUrl.match(urlPattern);

        if (match) {
            return {
