/**
 * Database migration script that reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationScript {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all migration files sorted by name/number
     * @returns {Array<string>} Array of sorted migration filenames
     */
    getMigrationFiles() {
        try {
            // Read the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            // Sort files by name (numerical prefix order)
            const sortedFiles = sqlFiles.sort((a, b) => {
                // Extract numeric prefixes from filenames
                const numA = this.extractNumberFromFilename(a);
                const numB = this.extractNumberFromFilename(b);

                if (numA !== null && numB !== null) {
                    return numA - numB;
                }

                // Fallback to alphabetical sorting if no numbers found
                return a.localeCompare(b);
            });

