 * and logs each filename it would apply, in order.
 */

// Read SQL files from the migrations directory
const migrationsDir = './migrations';

try {
    console.log('Reading migration files from:', migrationsDir);
    console.log('=========================================\n');

    // Get all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found.');
        console.log('Please add .sql files to the migrations directory.');
        process.exit(0);
    }

    // Sort files based on numeric prefix if available, otherwise alphabetically
    const sortedMigrations = sqlFiles.sort((a, b) => {
        // Extract numbers from the beginning of filenames
        const numA = a.match(/^(\d+)/);
        const numB = b.match(/^(\d+)/);

        if (numA && numB) {
            return parseInt(numA[1]) - parseInt(numB[1]);
        }

        // If no numbers found, sort alphabetically
        return a.localeCompare(b);
    });

    // Log each filename in the order they would be applied
    console.log(`Found ${sortedMigrations.length} migration file(s):\n`);
    sortedMigrations.forEach((filename, index) => {
        console.log(`${index + 1}. ${filename}`);
    });

    console.log('\nThese files would be applied in the order shown above.');

} catch (error) {
    if (error.code === 'ENOENT') {
        console.error(`Error: Migrations directory "${migrationsDir}" not found.`);
        console.error(`\nPlease create a directory structure:\n  ${migrationsDir}/`);
        console.error('\nAnd add your SQL migration files to it.');
    } else {
        console.error('Error:', error.message);
    }
    process.exit(1);
}

#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';
const SQL_FILE_EXTENSION = '.sql';

/**
 * Main function to run the migration script
 */
function main() {
    console.log('=== Database Migration Script ===\n');

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory "${MIGRATIONS_DIR}" not found.`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('Directory created. Please add SQL migration files to it.');
            return;
        }

        // Read all files from migrations directory
        const allFiles = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = allFiles.filter(file => 
            file.toLowerCase().endsWith(SQL_FILE_EXTENSION)
        );

        if (sqlFiles.length === 0) {
            console.log(`No SQL files found in "${MIGRATIONS_DIR}/" directory.`);
            console.log(`Please add migration files with "${SQL_FILE_EXTENSION}" extension.`);
            return;
        }

        // Sort files alphabetically (this ensures proper ordering)
        // For timestamp-based naming like "001_create_users.sql", "002_add_email.sql", etc.
        const sortedFiles = sqlFiles.sort();

        console.log(`Found ${sortedFiles.length} migration file(s):\n`);

        // Log each filename in order
        sortedFiles.forEach((filename, index) => {
            const filePath = path.join(MIGRATIONS_DIR, filename);
            const fileStats = fs.statSync(filePath);
            const fileSize = (fileStats.size / 1024).toFixed(2); // Convert to KB
            const modifiedDate = fileStats.mtime.toLocaleDateString();

            console.log(`${index + 1}. ${filename}`);
            console.log(`   Path: ${filePath}`);
            console.log(`   Size: ${fileSize} KB`);
            console.log(`   Last Modified: ${modifiedDate}`);
            console.log();
        });

        console.log('=== Migration Summary ===');
        console.log(`Total migrations to apply: ${sortedFiles.length}`);
        console.log('\nTo actually apply these migrations, you would:');
        console.log('1. Read each SQL file');
        console.log('2. Execute the SQL statements against your database');
        console.log('3. Track which migrations have been applied (e.g., in a migrations table)');

    } catch (error) {
        console.error(`Error running migration script: ${error.message}`);
        process.exit(1);
    }
}

// Run the script if executed directly
if (require.main === module) {
    main();
}

module.exports = { main };

-- Migration 001: Create users table
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on username for faster lookups
CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);

-- Create index on email for faster lookups
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);

-- Migration 003: Add user profile fields
ALTER TABLE users 
ADD COLUMN IF NOT EXISTS first_name VARCHAR(50),
ADD COLUMN IF NOT EXISTS last_name VARCHAR(50),
ADD COLUMN IF NOT EXISTS bio TEXT,
ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(255),
ADD COLUMN IF NOT EXISTS last_login TIMESTAMP;

-- Create a combined index for name searches
CREATE INDEX IF NOT EXISTS idx_users_name_search ON users(first_name, last_name);

-- Add a trigger to update updated_at timestamp
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

DROP TRIGGER IF EXISTS update_users_updated_at ON users;
CREATE TRIGGER update_users_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

