#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 * With local audit logging for tracking migration activities.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';
const SQL_FILE_EXTENSION = '.sql';
const ENV_FILE = '.env.test';
const DATABASE_URL_KEY = 'DATABASE_URL';
const AUDIT_LOG_FILE = './migration-audit.log';

/**
 * Write local audit log entry
 * @param {string} action - The action being logged
 * @param {object} data - Data to log
 */
function writeAuditLog(action, data) {
    try {
        const timestamp = new Date().toISOString();
        const logEntry = {
            timestamp,
            action,
            data,
            script: 'migrate.js',
            version: '1.0'
        };

        const logLine = JSON.stringify(logEntry) + '\n';

        // Append to audit log file
        fs.appendFileSync(AUDIT_LOG_FILE, logLine);
        console.log(`  ✓ Audit log written to: ${AUDIT_LOG_FILE}`);

    } catch (error) {
        console.warn(`  ⚠ Could not write to audit log: ${error.message}`);
    }
}

/**
 * Log migration plan locally
 * @param {Array} migrations - List of migration files
 * @param {string|null} databaseUrl - Database URL or null
 */
function logMigrationPlan(migrations, databaseUrl) {
    const plan = {
        timestamp: new Date().toISOString(),
        totalMigrations: migrations.length,
        migrations: migrations.map((file, index) => ({
            order: index + 1,
            filename: file,
            path: path.join(MIGRATIONS_DIR, file)
        })),
        databaseConfigured: !!databaseUrl,
        databaseType: databaseUrl ? parseDatabaseUrlComponents(databaseUrl).protocol : null
    };

    writeAuditLog('migration_plan_generated', plan);
}

/**
 * Parse environment file and extract DATABASE_URL
 * @returns {string|null} The DATABASE_URL or null if not found
 */
function parseDatabaseUrl() {
    try {
        if (!fs.existsSync(ENV_FILE)) {
            console.warn(`Warning: Environment file "${ENV_FILE}" not found.`);
            return null;
        }

        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            // Skip comments and empty lines
            if (line.trim().startsWith('#') || line.trim() === '') {
                continue;
            }

            const [key, ...valueParts] = line.split('=');
            if (key.trim() === DATABASE_URL_KEY) {
                const value = valueParts.join('=').trim();
                return value;
            }
        }

        console.warn(`Warning: "${DATABASE_URL_KEY}" not found in "${ENV_FILE}".`);
        return null;

    } catch (error) {
        console.warn(`Warning: Could not read "${ENV_FILE}": ${error.message}`);
        return null;
    }
}

/**
 * Parse a database URL into its components for logging
 * @param {string} databaseUrl - The database URL string
 * @returns {object} Parsed database URL components
 */
function parseDatabaseUrlComponents(databaseUrl) {
    try {
        // Parse the URL
        const url = new URL(databaseUrl);

        return {
            protocol: url.protocol.replace(':', ''),
            username: url.username,
            password: url.password ? '••••••••' : '(none)',
            host: url.hostname,
            port: url.port || '(default)',
            database: url.pathname.replace('/', ''),
            params: url.searchParams.toString() || '(none)'
        };
    } catch (error) {
        return {
            error: `Could not parse database URL: ${error.message}`,
            rawUrl: databaseUrl
        };
    }
}

/**
 * Main function to run the migration script
 */
function main() {
    console.log('=== Database Migration Script ===\n');

    try {
        // Step 1: Read and parse DATABASE_URL from .env.test
        console.log('Step 1: Reading database configuration...');
        const databaseUrl = parseDatabaseUrl();

        if (databaseUrl) {
            const dbComponents = parseDatabaseUrlComponents(databaseUrl);

            if (dbComponents.error) {
                console.log(`  Found DATABASE_URL: ${dbComponents.rawUrl}`);
            } else {
                console.log(`  Found DATABASE_URL: ${databaseUrl}`);
                console.log(`  Parsed components:`);
                console.log(`    - Protocol: ${dbComponents.protocol}`);
                console.log(`    - Username: ${dbComponents.username}`);
                console.log(`    - Password: ${dbComponents.password}`);
                console.log(`    - Host: ${dbComponents.host}`);
                console.log(`    - Port: ${dbComponents.port}`);
                console.log(`    - Database: ${dbComponents.database}`);
                console.log(`    - Parameters: ${dbComponents.params}`);
            }

            console.log('\n  ✓ Successfully loaded database configuration');
            console.log('  [Simulated] Connected to database successfully!\n');
        } else {
            console.log('  No DATABASE_URL found, running in dry-run mode\n');
        }

        // Step 2: Check if migrations directory exists
        console.log('Step 2: Checking migrations directory...');
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory "${MIGRATIONS_DIR}" not found.`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('Directory created. Please add SQL migration files to it.');
            return;
        }
        console.log(`  ✓ Migrations directory found: "${MIGRATIONS_DIR}"\n`);

        // Step 3: Read migration files
