#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

function loadEnvFile(filePath) {
    if (!fs.existsSync(filePath)) {
        return null;
    }

    const envContent = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
        // Skip comments and empty lines
        if (line.trim() === '' || line.startsWith('#')) {
            return;
        }

        // Split on first equals sign
        const equalsIndex = line.indexOf('=');
        if (equalsIndex > 0) {
            const key = line.substring(0, equalsIndex).trim();
            const value = line.substring(equalsIndex + 1).trim();

            // Remove surrounding quotes if present
            const trimmedValue = value.replace(/^(["'])(.*)\1$/, '$2');
            envVars[key] = trimmedValue;
        }
    });

    return envVars;
}

function getDatabaseUrl() {
    // Try to read from .env.test file
    const envFilePath = path.join(__dirname, '.env.test');
    const envVars = loadEnvFile(envFilePath);

    if (envVars && envVars.DATABASE_URL) {
        return envVars.DATABASE_URL;
    }

    // Fallback to environment variable
    return process.env.DATABASE_URL;
}

function maskDatabaseUrl(url) {
    // Simple masking of sensitive parts for safe logging
    if (!url) return null;

    try {
        // Parse the URL to mask the password
        const urlObj = new URL(url);
        if (urlObj.password) {
            urlObj.password = '***';
        }
        return urlObj.toString();
    } catch (error) {
        // If URL parsing fails, return a masked version
        return url.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
    }
}

function migrate() {
    console.log('🚀 Starting database migration script...\n');

    // Resolve and log database connection
    const databaseUrl = getDatabaseUrl();
    const maskedUrl = maskDatabaseUrl(databaseUrl);

    if (databaseUrl) {
        console.log(`🔌 Resolved DATABASE_URL: ${maskedUrl}`);
        console.log('✅ Would connect to database successfully\n');
    } else {
        console.log('⚠️  No DATABASE_URL found in .env.test or environment variables');
        console.log('📝 Please set DATABASE_URL in .env.test or as an environment variable\n');
    }

    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
