#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Simple env file loader
function loadEnvFile(filePath) {
    if (!fs.existsSync(filePath)) return null;

    const envContent = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
        line = line.trim();
        if (line === '' || line.startsWith('#')) return;

        const equalsIndex = line.indexOf('=');
        if (equalsIndex > 0) {
            const key = line.substring(0, equalsIndex).trim();
            const value = line.substring(equalsIndex + 1).trim();
            envVars[key] = value.replace(/^["']|["']$/g, '');
        }
    });

    return envVars;
}

// Get DATABASE_URL from .env.test or environment
function getDatabaseUrl() {
    const envVars = loadEnvFile(path.join(__dirname, '.env.test'));
    return (envVars && envVars.DATABASE_URL) || process.env.DATABASE_URL;
}

// Mask password in URL for safe logging
function maskUrl(url) {
    if (!url) return null;
    return url.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
}

// Main script
const databaseUrl = getDatabaseUrl();
if (databaseUrl) {
    console.log(`Database URL: ${maskUrl(databaseUrl)}`);
    console.log('Would connect to database successfully\n');
