#!/usr/bin/env node

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
        this.migrations = [];
    }

    /**
     * Read all SQL files from migrations directory and sort them
     */
    loadMigrations() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist.`);
                process.exit(1);
            }

            // Read all files in migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log(`No SQL migration files found in '${this.migrationsDir}'`);
                return;
            }

            // Sort files by name (alphabetical order which works for timestamp/numbered migrations)
            this.migrations = sqlFiles.sort();

            console.log(`Found ${this.migrations.length} migration file(s):`);

        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Display migrations in order
     */
    displayMigrations() {
        if (this.migrations.length === 0) {
            console.log('No migrations to display.');
            return;
        }

        console.log('\nMigrations to apply (in order):');
        console.log('=' .repeat(50));

        this.migrations.forEach((filename, index) => {
            const filepath = path.join(this.migrationsDir, filename);
            const fileInfo = fs.statSync(filepath);
            const sizeInKB = (fileInfo.size / 1024).toFixed(2);

            console.log(`${index + 1}. ${filename} (${sizeInKB} KB)`);

            // Optional: Show first few lines of each migration file
            if (index < 3) { // Just show preview for first few files
                try {
                    const content = fs.readFileSync(filepath, 'utf8');
                    const preview = content.split('\n').slice(0, 3).join('\n  ');
                    if (preview.trim()) {
                        console.log(`  Preview: ${preview}`);
                    }
                } catch (error) {
                    console.log(`  [Could not read file: ${error.message}]`);
                }
            }
        });

        console.log('=' .repeat(50));
        console.log(`Total: ${this.migrations.length} migration(s) ready to apply.`);
    }

    /**
     * Simulate applying migrations (just logging for now)
     */
    simulateApply() {
        if (this.migrations.length === 0) {
            console.log('\nNo migrations to apply.');
            return;
        }

        console.log('\nSimulating migration application:');
        console.log('-' .repeat(40));

        this.migrations.forEach((filename, index) => {
            const filepath = path.join(this.migrationsDir, filename);
            console.log(`[Step ${index + 1}] Would apply: ${filename}`);

            // Here you would normally:
            // 1. Read the SQL file
            // 2. Execute it against the database
            // 3. Log success/failure
            // 4. Update migration tracking table
        });

        console.log('-' .repeat(40));
        console.log('Simulation complete. No actual database changes were made.');
    }

    /**
     * Main execution method
     */
    run() {
        console.log('Database Migration Script');
        console.log('========================\n');

        this.loadMigrations();
        this.displayMigrations();

        // Optional: Ask for confirmation before applying
        console.log('\nTo actually apply these migrations, you would need to:');
        console.log('1. Set up database connection parameters');
        console.log('2. Implement actual SQL execution');
        console.log('3. Add migration tracking table');
        console.log('4. Add rollback capability');

        this.simulateApply();
    }
}

// Command line interface
if (require.main === module) {
    const args = process.argv.slice(2);
    const command = args[0] || 'list';

    const runner = new MigrationRunner();

    switch (command) {
        case 'list':
        case '--list':
        case '-l':
            runner.loadMigrations();
            runner.displayMigrations();
            break;

        case 'apply':
        case '--apply':
        case '-a':
            console.log('Note: Actual application not implemented yet.');
            console.log('Running in simulation mode...\n');
            runner.run();
            break;

        case 'help':
        case '--help':
        case '-h':
            console.log(`
Database Migration Script Usage:

  node migrate.js [command]

Commands:
  list, --list, -l    List all migrations (default)
  apply, --apply, -a  Simulate applying migrations
  help, --help, -h    Show this help message

Options:
  --dir <path>        Specify custom migrations directory
                      Example: node migrate.js list --dir ./custom-migrations

Examples:
  node migrate.js                    # List migrations
  node migrate.js list              # Same as above
  node migrate.js apply             # Simulate applying migrations
  node migrate.js --dir ./db/changes list  # List from custom directory
            `);
            break;

        default:
            // Check for --dir option
            const dirIndex = args.indexOf('--dir');
            if (dirIndex !== -1 && args[dirIndex + 1]) {
                const customDir = args[dirIndex + 1];
                const runner = new MigrationRunner(customDir);
                runner.loadMigrations();
                runner.displayMigrations();
            } else {
                console.log(`Unknown command: ${command}`);
                console.log('Use "node migrate.js help" for usage information.');
            }
    }
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

