/**
 * Mask sensitive parts of database URL for logging
 */
maskDatabaseUrl(url) {
    try {
        // Parse the URL to mask password
        const urlPattern = /^([^:]+):\/\/([^:]+):([^@]+)@(.+)$/;
        const match = url.match(urlPattern);

        if (match) {
            const [_, protocol, username, password, rest] = match;
            // Mask the password with asterisks
            const maskedPassword = '*'.repeat(Math.min(password.length, 8));
            return `${protocol}://${username}:${maskedPassword}@${rest}`;
        }

        // If parsing fails, return a truncated version
        return url.substring(0, Math.min(url.length, 50)) + 
               (url.length > 50 ? '...' : '');
