function readDatabaseUrl(envFile = '.env.test') {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(envFile)) {
            console.warn(`Warning: Environment file '${envFile}' not found.`);
            return null;
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(envFile, 'utf8');

        // Parse the file line by line to find DATABASE_URL
        const lines = envContent.split('\n');
        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Look for DATABASE_URL
            if (trimmedLine.startsWith('DATABASE_URL=')) {
                const databaseUrl = trimmedLine.substring('DATABASE_URL='.length);

                // Log connection success (simulated)
                console.log(`✓ Connected to database successfully (simulated)`);

                // Mask password for safe logging
                const maskedUrl = maskDatabaseUrl(databaseUrl);
                console.log(`  Connection string: ${maskedUrl}`);

                return databaseUrl;
            }
        }

        console.warn(`Warning: DATABASE_URL not found in ${envFile}`);
        return null;

    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

function maskDatabaseUrl(url) {
    try {
        // Parse the URL to mask password
        const urlPattern = /^([^:]+):\/\/([^:]+):([^@]+)@(.+)$/;
        const match = url.match(urlPattern);

        if (match) {
            const [_, protocol, username, password, rest] = match;
            // Mask the password with asterisks
            const maskedPassword = '*'.repeat(Math.min(password.length, 8));
            return `${protocol}://${username}:${maskedPassword}@${rest}`;
        }

        // If parsing fails, return a truncated version
        return url.substring(0, Math.min(url.length, 50)) + 
               (url.length > 50 ? '...' : '');
    } catch (error) {
