/**
 * Make HTTP POST request to audit service
 */
makeAuditRequest(data) {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify(data);

        const url = new URL(this.auditServiceUrl);
        const options = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData),
                'User-Agent': 'Migration-Audit-Script/1.0'
            },
            timeout: 10000 // 10 second timeout
        };

        const protocol = url.protocol === 'https:' ? https : http;
        const req = protocol.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`  Audit service response: ${res.statusCode} ${res.statusMessage}`);
                    if (responseData) {
                        try {
                            const parsed = JSON.parse(responseData);
                            console.log(`  Service message: ${parsed.message || 'OK'}`);
                        } catch {
                            // Ignore parsing errors for response body
                        }
                    }
                    resolve(true);
                } else {
                    console.warn(`  Audit service responded with: ${res.statusCode} ${res.statusMessage}`);
                    if (responseData) {
                        console.warn(`  Response: ${responseData.substring(0, 200)}`);
                    }
                    resolve(false); // Don't reject, just return false
                }
            });
        });

        req.on('error', (error) => {
            console.warn(`  Audit service connection error: ${error.message}`);
            resolve(false); // Don't reject, just return false to continue
        });

        req.on('timeout', () => {
            req.destroy();
            console.warn('  Audit service request timed out (10s)');
            resolve(false); // Don't reject, just return false to continue
        });

        req.write(postData);
        req.end();
    });
}

