#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Main migration script
 * Reads SQL files from the migrations directory and logs them in order
 */
async function runMigrations() {
  try {
    console.log('Starting migration process...');
    console.log(`Looking for migrations in: ${path.resolve(MIGRATIONS_DIR)}`);

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log(`Created directory: ${path.resolve(MIGRATIONS_DIR)}`);
      console.log('No migrations to apply. Place SQL files in the migrations directory.');
      process.exit(0);
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (support .sql extension)
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sort alphabetically to ensure order

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in migrations directory.');
      console.log('Expected files with .sql extension.');
      process.exit(0);
    }

    console.log(`\nFound ${sqlFiles.length} migration file(s):`);
    console.log('='.repeat(50));

    // Log each migration file in order
    sqlFiles.forEach((file, index) => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      const fileSize = fs.statSync(filePath).size;

      console.log(`${index + 1}. ${file}`);
      console.log(`   Path: ${path.resolve(filePath)}`);
      console.log(`   Size: ${fileSize} bytes`);

      // Optional: Show first few lines of each SQL file
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n').slice(0, 3); // First 3 lines
        const preview = lines.join('\n   ');
        if (preview.trim()) {
          console.log(`   Preview: ${preview}`);
        }
      } catch (err) {
        console.log(`   Could not read file: ${err.message}`);
      }

      console.log('');
    });

    console.log('='.repeat(50));
    console.log('Migration files listed above would be applied in this order.');
    console.log('\nNote: This script only logs the files. To actually apply the migrations,');
    console.log('you would need to add database connection logic and execute the SQL.');

  } catch (error) {
    console.error('Error during migration process:', error);
    process.exit(1);
  }
}

// Run the script
if (require.main === module) {
  runMigrations();
}

module.exports = { runMigrations };

