/**
 * Parse .env file and extract key-value pairs
 * @param {string} envPath - Path to the .env file
 * @returns {Object} - Object containing environment variables
 */
function parseEnvFile(envPath) {
  try {
    if (!fs.existsSync(envPath)) {
      console.warn(`Warning: Environment file '${envPath}' not found.`);
      return {};
    }

    const content = fs.readFileSync(envPath, 'utf8');
    const envVars = {};

    // Parse each line
    content.split('\n').forEach(line => {
      line = line.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse key=value pairs
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove quotes if present
        if (value.startsWith('"') && value.endsWith('"')) {
          value = value.slice(1, -1);
        } else if (value.startsWith("'") && value.endsWith("'")) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.warn(`Warning: Could not parse environment file '${envPath}':`, error.message);
    return {};
  }
}

/**
 * Extract and mask sensitive parts of database URL for logging
 * @param {string} databaseUrl - Full database URL
 * @returns {string} - Masked database URL for safe logging
 */
function maskDatabaseUrl(databaseUrl) {
  if (!databaseUrl) return '';

  try {
    // Parse the URL to mask password
    const url = new URL(databaseUrl);

    // Mask password if present
    if (url.password) {
      url.password = '*****';
    }

    // Reconstruct URL with masked password
    const maskedUrl = `${url.protocol}//${url.username}:${url.password}@${url.host}${url.pathname}`;

    // Add query parameters if present
    if (url.search) {
      return maskedUrl + url.search;
    }

    return maskedUrl;
  } catch (error) {
    // If URL parsing fails, try a simple masking
    const masked = databaseUrl.replace(/:[^:@]+@/, ':*****@');
    return masked || databaseUrl;
