#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

function main() {
    const migrationsDir = path.join(__dirname, 'migrations');

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Migrations directory '${migrationsDir}' does not exist.`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(migrationsDir, { recursive: true });
            console.log('Migrations directory created. No migration files found.');
            process.exit(0);
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files (files ending with .sql)
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in ./migrations/ directory.');
            return;
        }

        // Sort files in natural order to ensure proper migration sequence
        // This handles numeric prefixes like 001_create_table.sql, 002_add_column.sql, etc.
        sqlFiles.sort((a, b) => {
            // Try to extract numeric prefixes for better sorting
            const numMatchA = a.match(/^(\d+)_/);
            const numMatchB = b.match(/^(\d+)_/);

            if (numMatchA && numMatchB) {
                return parseInt(numMatchA[1]) - parseInt(numMatchB[1]);
            }

            // If files don't have numeric prefixes, sort alphabetically
            return a.localeCompare(b);
        });

        console.log('Migration script would apply the following SQL files in order:');
        console.log('===============================================================');

        // Log each filename with its position
        sqlFiles.forEach((filename, index) => {
            console.log(`${index + 1}. ${filename}`);
        });

        console.log('===============================================================');
        console.log(`Total: ${sqlFiles.length} migration file(s) found.`);

        // Optional: Show details about each file
        console.log('\nFile details:');
        console.log('--------------');
        sqlFiles.forEach((filename, index) => {
            const filePath = path.join(migrationsDir, filename);
            const stats = fs.statSync(filePath);
            const content = fs.readFileSync(filePath, 'utf8');
            const lines = content.split('\n').length;

            console.log(`${index + 1}. ${filename}`);
            console.log(`   Size: ${stats.size} bytes`);
            console.log(`   Lines: ${lines}`);
            console.log(`   Created: ${stats.birthtime.toLocaleString()}`);
            console.log(`   Modified: ${stats.mtime.toLocaleString()}`);
            console.log('');
        });

    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        process.exit(1);
    }
}

// Run the script if called directly
if (require.main === module) {
    main();
}

module.exports = { main };

-- Create users table
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    email VARCHAR(100) NOT NULL UNIQUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on username for faster lookups
CREATE INDEX idx_users_username ON users(username);

-- Create index on email
