#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

function readDatabaseUrl() {
    const envFilePath = path.join(__dirname, '.env.test');

    try {
        if (!fs.existsSync(envFilePath)) {
            console.warn(`Warning: .env.test file not found at '${envFilePath}'`);
            console.warn('Continuing without database connection...');
            return null;
        }

        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            // Skip comments and empty lines
            if (line.trim() === '' || line.trim().startsWith('#')) {
                continue;
            }

            // Look for DATABASE_URL
            const match = line.match(/^\s*DATABASE_URL\s*=\s*(.+?)\s*$/);
            if (match) {
                const dbUrl = match[1].trim();
                console.log(`✓ Found DATABASE_URL in .env.test`);

                // Mask sensitive parts of the URL for security
                const maskedUrl = maskDatabaseUrl(dbUrl);
                console.log(`  Masked URL: ${maskedUrl}`);

                return dbUrl;
            }
        }

        console.warn('Warning: DATABASE_URL not found in .env.test file');
        console.warn('Continuing without database connection...');
        return null;

    } catch (error) {
        console.error(`Error reading .env.test file: ${error.message}`);
        console.warn('Continuing without database connection...');
        return null;
    }
}

